package nexusbench

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"slices"
	"strings"
)

func repositorySpecs(p Params) []repositorySpec {
	pv := &provisioner{p: p}
	return pv.repositories()
}

func CutUpstream(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
	if out == nil {
		out = io.Discard
	}
	if !p.UpstreamIsBench() {
		return customUpstreamError(p)
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
	state, err := d.readUpstream(ctx)
	if err != nil {
		return err
	}
	switch state {
	case UpstreamMissing:
		return &BenchError{Kind: Unclassified, Cause: "the Deployment " + upstreamDeployment + " does not exist", Check: "run `mise run nexus-bench:up`"}
	case UpstreamCut:
		d.say("the upstream is already cut")
	default:
		d.say("scaling the upstream to zero replicas")
		if err := d.scaleUpstream(ctx, 0); err != nil {
			return err
		}
	}
	return d.waitUpstreamGone(ctx)
}

func (d *deployer) waitUpstreamGone(ctx context.Context) error {
	deadline := d.clk.Now().Add(d.pf.p.Timeout)
	for {
		var pods struct {
			Items []podObject `json:"items"`
		}
		if err := d.read(ctx, "read the upstream pods", d.podsArgs(), &pods); err != nil {
			return err
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		if len(pods.Items) == 0 {
			d.say("no pod of the upstream is left")
			return nil
		}
		if !d.clk.Now().Before(deadline) {
			var names []string
			for _, pd := range pods.Items {
				names = append(names, pd.Metadata.Name)
			}
			return &BenchError{Kind: Deadline,
				Cause: fmt.Sprintf("the pods %s of the upstream are still there after %s", strings.Join(names, ", "), d.pf.p.Timeout),
				Check: describePodCommand(d.pf.p, d.w) + ", then raise " + envTimeout}
		}
		if err := d.clk.Sleep(ctx, upstreamPollInterval); err != nil {
			return err
		}
	}
}

var benchRepositories = []string{dockerGroupRepository, dockerProxyRepository, dockerHostedRepository}

func (c *client) deleteRepository(ctx context.Context, name string) (bool, error) {
	if !slices.Contains(benchRepositories, name) {
		return false, errors.New("refused to delete a repository outside the bench")
	}
	resp, err := c.do(ctx, request{op: "delete the repository " + name, method: http.MethodDelete, path: restAPI + "/repositories/" + name})
	if err != nil {
		return false, err
	}
	switch {
	case resp.status == http.StatusNotFound:
		return false, nil
	case resp.status < 200 || resp.status > 299:
		return false, &APIError{Op: "delete the repository " + name, Status: resp.status}
	}
	return true, nil
}

func (c *client) invalidateCache(ctx context.Context, name string) error {
	_, err := c.expect(ctx, request{op: "invalidate the cache of " + name, method: http.MethodPost, path: restAPI + "/repositories/" + name + "/invalidate-cache"})
	return err
}

func (c *client) unblockProxy(ctx context.Context, p Params) error {
	path := dockerReposPath + "/proxy/" + dockerProxyRepository
	found, err := c.get(ctx, "read the proxy repository "+dockerProxyRepository, path, nil, nil)
	if err != nil {
		return err
	}
	if !found {
		return &BenchError{Kind: ProvisionFailed, Cause: "the proxy repository does not exist", Check: upCheck}
	}
	for _, spec := range repositorySpecs(p) {
		if spec.name == dockerProxyRepository {
			if err := c.write(ctx, "update the proxy repository "+spec.name, http.MethodPut, path, spec.config); err != nil {
				return err
			}
		}
	}
	return c.invalidateCache(ctx, dockerProxyRepository)
}

func (c *client) requireAdmin(ctx context.Context) error {
	resp, err := c.do(ctx, request{op: "check the admin account", method: http.MethodGet, path: usersPath, query: url.Values{"userId": {adminUserID}}})
	if err != nil {
		return err
	}
	switch {
	case resp.status == http.StatusUnauthorized || resp.status == http.StatusForbidden:
		return &BenchError{Kind: ProvisionFailed, Cause: "Nexus refused the stored admin password, so nothing was changed", Check: "run `mise run nexus-bench:down` then `mise run nexus-bench:up`"}
	case resp.status < 200 || resp.status > 299:
		return &APIError{Op: "check the admin account", Status: resp.status}
	}
	return nil
}

func UnblockProxy(ctx context.Context, store SecretStore, baseURL string, p Params, out io.Writer) error {
	if out == nil {
		out = io.Discard
	}
	if !p.UpstreamIsBench() {
		return customUpstreamError(p)
	}
	c, _, err := adminFromStore(ctx, baseURL, store)
	if err != nil {
		return asBenchError(err, p, baseURL)
	}
	defer c.closeIdle()
	fmt.Fprintln(out, "restore: putting the proxy back in service")
	if err := c.unblockProxy(ctx, p); err != nil {
		return asBenchError(err, p, baseURL)
	}
	return nil
}

//     wrap it with asBenchError, as Provision does). A name outside
//     benchRepositories is refused before any request, with an error that is
//     neither an *APIError nor a transport error.
//   - benchRepositories is exactly [docker-group, docker-proxy, docker-hosted], in
//     this order: the group names the two others.
//   - invalidateCache sends POST /service/rest/v1/repositories/{name}/invalidate-cache
//     and expects a 2xx; it is not limited to the bench repositories (it writes no
//     data).
//   - unblockProxy reads the proxy (404: an error that says `nexus-bench:up`, no
//     write), PUTs the configuration of repositorySpecs(p) for docker-proxy (never a
//     configuration read back from the instance), then invalidates the cache. The
//     order GET, PUT, POST is the sequence of the plan.
//   - requireAdmin sends one GET as admin; a refused password (401 or 403) is a
//     *BenchError of kind ProvisionFailed whose message says nothing was changed.
//   - UnblockProxy refuses an upstream the bench did not deploy before any
//     request, and reports as `restore: ...` lines.
//
// What depends on the measures of step 0 (to confirm before the code is written):
//   - H-UNBLOCK: that a PUT of the proxy configuration followed by an
//     invalidate-cache is what puts the proxy back in service. If the measure says
//     the PUT alone, or the POST alone, is enough (or neither), the sequence tests
//     below (TestUnblockProxySequence*) and the fake's "blocked" state change.
//   - H-INVAL: the answer code of invalidate-cache (204 here) and whether it
//     accepts a proxy and a group but not a hosted repository (400 here).
//   - H-REPODEL: the answer codes of DELETE (204 and 404 here) and the shape of a
//     recreated repository (empty at once here, see KeepComponentsAfterDelete).

// provisionedBench is a bench whose Nexus is provisioned against the upstream the
// bench deploys, the way a bench after "up" is: the three repositories, an admin
// password the store holds, the upstream allowed in the SSRF protection.
func provisionedBench(t *testing.T) *bench {
	t.Helper()
	b := newBench(t)
	b.p.UpstreamURL = upstreamFor(b.p.Namespace)
	if !b.p.UpstreamIsBench() {
		t.Fatalf("the bench upstream %q is not the bench's", b.p.UpstreamURL)
	}
	b.mustRun()
	b.ip.ok = false
	return b
}

// admin is a client authenticated with the admin password the store holds.
func (b *bench) admin() *client {
	b.t.Helper()
	c := newClient(b.nexus.URL(), adminUserID, b.store.current().AdminPassword)
	b.t.Cleanup(c.closeIdle)
	return c
}

