func TestUnblockProxyIsIdempotent(t *testing.T) {
	b := provisionedBench(t)
	c := b.admin()
	for i := range 2 {
		if err := c.unblockProxy(context.Background(), b.p); err != nil {
			t.Fatalf("unblockProxy #%d: %v", i+1, err)
